export function getProductSlug(product: Product): string {
  return product.sku.toLowerCase();
}

export function getProductImage(product: Product): string {
  if (productImageMap[product.name]) return productImageMap[product.name];
  if (pumpImages[product.name]) return pumpImages[product.name];
  if (legacyImages[product.name]) return legacyImages[product.name];
  return '';
}
